use crate::test_support::{create_node, start_node, node_id, kill};
use madsim::{net::NetSim, fs::FsSim, plugin::simulator};
use super::{client::Clerk, server::ShardKvServer};
use crate::shard_ctrler::{client::Clerk as CtrlerClerk, server::ShardCtrler, N_SHARDS};
use ::rand::distributions::Alphanumeric;
use madsim::{
    rand::{self, Rng},
    time::*,
    runtime::Handle,
};
use std::{
    collections::{HashMap, HashSet},
    net::SocketAddr,
    sync::{Arc, Mutex},
};

pub struct Tester {
    handle: Handle,
    n: usize,

    ctrler_addrs: Vec<SocketAddr>,
    _ctrlers: Vec<Arc<ShardCtrler>>,
    ctrler_ck: CtrlerClerk,

    groups: Vec<Group>,

    max_raft_state: Option<usize>,

    // begin()/end() statistics
    t0: Instant,
}

struct Group {
    gid: u64,
    addrs: Vec<SocketAddr>,
    servers: Mutex<Vec<Option<Arc<ShardKvServer>>>>,
}

impl Tester {
    pub async fn new(n: usize, unreliable: bool, max_raft_state: Option<usize>) -> Tester {
        let handle = Handle::current();
        if unreliable {
            NetSim::current().update_config(|cfg| {
                cfg.packet_loss_rate = 0.1;
                cfg.send_latency = Duration::from_millis(1)..Duration::from_millis(27);
            });
        }

        let n_ctrler = 3;
        let ctrler_addrs = (0..n_ctrler)
            .map(|i| SocketAddr::from(([0, 0, 1, i as _], 1)))
            .collect::<Vec<_>>();
        let mut ctrlers = vec![];
        for i in 0..n_ctrler {
            create_node(&handle, ctrler_addrs[i]);
            let handle = start_node(&handle, ctrler_addrs[i]);
            let ctrler = handle
                .spawn(ShardCtrler::new(ctrler_addrs.clone(), i, max_raft_state))
                .await.unwrap();
            ctrlers.push(ctrler);
        }
        let ctrler_ck = CtrlerClerk::new(ctrler_addrs.clone());

        let n_groups: usize = 3;
        let groups: Vec<Group> = (0..n_groups)
            .map(|i| Group {
                gid: i as u64 + 100,
                addrs: (0..n)
                    .map(|j| SocketAddr::from(([0, 1, i as _, j as _], 1)))
                    .collect(),
                servers: Mutex::new(vec![None; n]),
            })
            .collect();

        for group in &groups {
            for &addr in &group.addrs { create_node(&handle, addr); }
        }

        let tester = Tester {
            handle,
            n,
            ctrler_addrs,
            _ctrlers: ctrlers,
            ctrler_ck,
            groups,
            max_raft_state,
            t0: Instant::now(),
        };
        for g in 0..n_groups {
            for i in 0..n {
                tester.start_server(g, i).await;
            }
        }
        tester
    }

    /// check that no server's log is too big.
    pub fn check_logs(&self) {
        for group in self.groups.iter() {
            for &addr in group.addrs.iter() {
                let state_size = simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "state").unwrap_or(0);
                let snap_size = simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "snapshot").unwrap_or(0);
                if let Some(limit) = self.max_raft_state {
                    assert!(
                        state_size as usize <= 8 * limit,
                        "raft state size {} exceed limit {}",
                        state_size,
                        limit
                    );
                } else {
                    assert_eq!(
                        snap_size, 0,
                        "max_raft_state is None, but snapshot is non-empty!"
                    );
                }
            }
        }
    }

    pub fn total_size(&self) -> u64 {
        let mut size = 0;
        for group in self.groups.iter() {
            for &addr in group.addrs.iter() {
                let state_size = simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "state").unwrap();
                let snap_size = simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "snapshot").unwrap();
                size += state_size + snap_size;
            }
        }
        size
    }

    fn rpc_total(&self) -> u64 {
        NetSim::current().stat().msg_count / 2
    }

    // Create a clerk with clerk specific server names.
    // Give it connections to all of the servers
    pub fn make_client(&self) -> Clerk {
        Clerk::new(self.ctrler_addrs.clone())
    }

    /// Start i'th server of group.
    pub async fn start_server(&self, group: usize, i: usize) {
        debug!("start_server({}, {})", group, i);
        let group = &self.groups[group];
        let addrs = group.addrs.clone();
        let handle = start_node(&self.handle, group.addrs[i]);
        let ctrl_ck = CtrlerClerk::new(self.ctrler_addrs.clone());
        let kv = handle
            .spawn(ShardKvServer::new(
                ctrl_ck,
                addrs,
                group.gid,
                i,
                self.max_raft_state,
            ))
            .await.unwrap();
        group.servers.lock().unwrap()[i] = Some(kv);
    }

    /// Shutdown i'th server of group.
    pub fn shutdown_server(&self, group: usize, i: usize) {
        debug!("shutdown_server({}, {})", group, i);
        let group = &self.groups[group];
        kill(&self.handle, group.addrs[i]);
        group.servers.lock().unwrap()[i] = None;
    }

    pub async fn start_group(&self, group: usize) {
        for i in 0..self.n {
            self.start_server(group, i).await;
        }
    }

    pub fn shutdown_group(&self, group: usize) {
        for i in 0..self.n {
            self.shutdown_server(group, i);
        }
    }

    // tell the shardctrler that a group is joining.
    pub async fn join(&self, group: usize) {
        self.joins(&[group]).await;
    }

    pub async fn joins(&self, groups: &[usize]) {
        debug!("join({:?})", groups);
        let mut m = HashMap::new();
        for &g in groups {
            let gid = self.groups[g].gid;
            let names = self.groups[g].addrs.clone();
            m.insert(gid, names);
        }
        self.ctrler_ck.join(m).await;
    }

    // tell the shardctrler that a group is leaving.
    pub async fn leave(&self, group: usize) {
        self.leaves(&[group]).await;
    }

//! Asynchronous file system.

use spin::{Mutex, RwLock};
use std::{
    collections::HashMap,
    fmt,
    io::{Error, ErrorKind, Result},
    path::{Path, PathBuf},
    sync::Arc,
};
use tracing::*;

use crate::{
    plugin::{node, simulator, Simulator},
    rand::GlobalRng,
    task::NodeId,
    time::TimeHandle,
    Config,
};

/// File system simulator.
#[cfg_attr(docsrs, doc(cfg(madsim)))]
#[derive(Default)]
pub struct FsSim {
    handles: Mutex<HashMap<NodeId, FsNodeHandle>>,
}

impl Simulator for FsSim {
    fn new(_rand: &GlobalRng, _time: &TimeHandle, _config: &Config) -> Self {
        Default::default()
    }

    fn create_node(&self, id: NodeId) {
        let mut handles = self.handles.lock();
        handles.insert(id, FsNodeHandle::new());
    }

    fn reset_node(&self, id: NodeId) {
        self.power_fail(id);
    }
}

impl FsSim {
    /// Return a handle of the specified node.
    fn get_node(&self, id: NodeId) -> FsNodeHandle {
        let handles = self.handles.lock();
        handles[&id].clone()
    }

    /// Simulate a power failure. All data that does not reach the disk will be lost.
    pub fn power_fail(&self, _id: NodeId) {
        // TODO
    }

    /// Get the size of given file.
    pub fn get_file_size(&self, node: NodeId, path: impl AsRef<Path>) -> Result<u64> {
        let path = path.as_ref();
        let handle = self.handles.lock()[&node].clone();
        let fs = handle.fs.lock();
        let inode = fs
            .get(path)
            .ok_or_else(|| Error::new(ErrorKind::NotFound, format!("file not found: {path:?}")))?;
        Ok(inode.metadata().len())
    }
}

/// File system simulator for a node.
#[derive(Clone)]
struct FsNodeHandle {
    fs: Arc<Mutex<HashMap<PathBuf, Arc<INode>>>>,
}

impl FsNodeHandle {
    fn new() -> Self {
        FsNodeHandle {
            fs: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn current() -> Self {
        simulator::<FsSim>().get_node(node())
    }

    async fn open(&self, path: impl AsRef<Path>) -> Result<File> {
        let path = path.as_ref();
        trace!(?path, "open file");
        let fs = self.fs.lock();
        let inode = fs
            .get(path)
            .ok_or_else(|| Error::new(ErrorKind::NotFound, format!("file not found: {path:?}")))?
            .clone();
        Ok(File {
            inode,
            can_write: false,
        })
    }

    async fn create(&self, path: impl AsRef<Path>) -> Result<File> {
        let path = path.as_ref();
        trace!(?path, "create file");
        let mut fs = self.fs.lock();
        let inode = fs
            .entry(path.into())
            .and_modify(|inode| inode.truncate())
            .or_insert_with(|| Arc::new(INode::new(path)))
            .clone();
        Ok(File {
            inode,
            can_write: true,
        })
    }

    async fn metadata(&self, path: impl AsRef<Path>) -> Result<Metadata> {
        let path = path.as_ref();
        let fs = self.fs.lock();
        let inode = fs
            .get(path)
            .ok_or_else(|| Error::new(ErrorKind::NotFound, format!("file not found: {path:?}")))?;
        Ok(inode.metadata())
    }
}

struct INode {
    path: PathBuf,
    data: RwLock<Vec<u8>>,
}

impl INode {
    fn new(path: &Path) -> Self {
        INode {
            path: path.into(),
            data: RwLock::new(Vec::new()),
        }
    }

    fn truncate(&self) {
        self.data.write().clear();
    }

    fn metadata(&self) -> Metadata {
        Metadata {
            len: self.data.read().len() as u64,
        }
    }
}

/// A reference to an open file on the filesystem.
pub struct File {
    inode: Arc<INode>,
    can_write: bool,
}

impl fmt::Debug for File {
    fn fmt(&self, fmt: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt.debug_struct("File")
            .field("path", &self.inode.path)
            .finish()
    }
}

impl File {
    /// Attempts to open a file in read-only mode.
    pub async fn open(path: impl AsRef<Path>) -> Result<File> {
        let handle = FsNodeHandle::current();
        handle.open(path).await
    }

    /// Opens a file in write-only mode.
    ///
    /// This function will create a file if it does not exist, and will truncate it if it does.
    pub async fn create(path: impl AsRef<Path>) -> Result<File> {
        let handle = FsNodeHandle::current();
        handle.create(path).await
    }

    /// Reads a number of bytes starting from a given offset.
    #[instrument(skip(buf), fields(len = buf.len()))]
    pub async fn read_at(&self, buf: &mut [u8], offset: u64) -> Result<usize> {
        let data = self.inode.data.read();
        let end = data.len().min(offset as usize + buf.len());
        let len = end - offset as usize;
        buf[..len].copy_from_slice(&data[offset as usize..end]);
        // TODO: random delay
        Ok(len)
    }

    /// Attempts to write an entire buffer starting from a given offset.
    #[instrument(skip(buf), fields(len = buf.len()))]
    pub async fn write_all_at(&self, buf: &[u8], offset: u64) -> Result<()> {
        if !self.can_write {
            return Err(Error::new(
                ErrorKind::PermissionDenied,
                "the file is read only",
            ));
        }
        let mut data = self.inode.data.write();
        let end = data.len().min(offset as usize + buf.len());
        let len = end - offset as usize;
        data[offset as usize..end].copy_from_slice(&buf[..len]);
        if len < buf.len() {
            data.extend_from_slice(&buf[len..]);
        }
        // TODO: random delay
        // TODO: simulate buffer, write will not take effect until flush or close
        Ok(())
    }

    /// Truncates or extends the underlying file, updating the size of this file to become `size`.
    #[instrument]
    pub async fn set_len(&self, size: u64) -> Result<()> {
        let mut data = self.inode.data.write();
        data.resize(size as usize, 0);
        // TODO: random delay
        Ok(())
    }

    /// Attempts to sync all OS-internal metadata to disk.
    #[instrument]
    pub async fn sync_all(&self) -> Result<()> {
        // TODO: random delay
        Ok(())
    }

    /// Queries metadata about the underlying file.
    #[instrument]
    pub async fn metadata(&self) -> Result<Metadata> {
        Ok(self.inode.metadata())
    }
}

/// Read the entire contents of a file into a bytes vector.
pub async fn read(path: impl AsRef<Path>) -> Result<Vec<u8>> {
    let handle = FsNodeHandle::current();
    let file = handle.open(path).await?;
    let data = file.inode.data.read().clone();
    // TODO: random delay
    Ok(data)
}

/// Given a path, query the file system to get information about a file, directory, etc.
pub async fn metadata(path: impl AsRef<Path>) -> Result<Metadata> {
    let handle = FsNodeHandle::current();
    handle.metadata(path).await
}

/// Metadata information about a file.
pub struct Metadata {
    len: u64,
}

impl Metadata {
    /// Returns the size of the file, in bytes, this metadata is for.
    #[allow(clippy::len_without_is_empty)]
    pub fn len(&self) -> u64 {
        self.len
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::runtime::Runtime;

    #[test]
    fn create_open_read_write() {
        let runtime = Runtime::new();
        let node = runtime.create_node().build();
        let f = node.spawn(async move {
            assert_eq!(
                File::open("file").await.err().unwrap().kind(),
                ErrorKind::NotFound
            );
            let file = File::create("file").await.unwrap();
            file.write_all_at(b"hello", 0).await.unwrap();

            let mut buf = [0u8; 10];
            let read_len = file.read_at(&mut buf, 2).await.unwrap();
            assert_eq!(read_len, 3);
            assert_eq!(&buf[..3], b"llo");
            drop(file);

            // writing to a read-only file should be denied
            let rofile = File::open("file").await.unwrap();
            assert_eq!(
                rofile.write_all_at(b"gg", 0).await.err().unwrap().kind(),
                ErrorKind::PermissionDenied
            );

            // create should truncate existing file
            let file = File::create("file").await.unwrap();
            let read_len = file.read_at(&mut buf, 0).await.unwrap();
            assert_eq!(read_len, 0);
        });
        runtime.block_on(f).unwrap();
    }
}

