//"'! Synchronous Raft engine. Networking/storage are confined to raft.rs.
//! The scalar guards in state.rs are verified; full transition verification is
//! still required (see proof/README.md).
use super::state::{self, Role, State};
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Entry { pub term: u64, pub data: Vec<u8> }

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Durable {
    pub term: u64,
    pub voted_for: Option<usize>,
    pub base: u64,
    pub base_term: u64,
    pub log: Vec<Entry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Vote {
    pub term: u64, pub candidate: usize, pub last_index: u64, pub last_term: u64,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VoteReply { pub term: u64, pub granted: bool }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Append {
    pub term: u64, pub leader: usize, pub prev: u64, pub prev_term: u64,
    pub entries: Vec<Entry>, pub commit: u64,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AppendReply { pub term: u64, pub success: bool, pub next: u64 }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Install {
    pub term: u64, pub leader: usize, pub index: u64, pub last_term: u64, pub data: Vec<u8>,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InstallReply { pub term: u64, pub accepted: bool }

pub enum Replication { Append(Append), Snapshot(Install) }
pub enum Applied { Command { index: u64, data: Vec<u8> }, Snapshot { index: u64, term: u64, data: Vec<u8> } }

pub struct Core {
    pub state: State,
    pub me: usize,
    pub members: usize,
    pub base: u64,
    pub base_term: u64,
    pub log: Vec<Entry>,
    pub snapshot: Vec<u8>,
    pub commit: u64,
    pub applied: u64,
    pub leader: usize,
    pub reset_timer: bool,
    pub dirty: bool,
    next: Vec<u64>,
    matched: Vec<u64>,
    votes: Vec<bool>,
    pending_snapshot: bool,
}

impl Core {
    pub fn new(me: usize, members: usize) -> Self {
        assert!(members > 0 && me < members);
        Self {
            state: State::initial(), me, members, base: 0, base_term: 0,
            log: vec![], snapshot: vec![], commit: 0, applied: 0, leader: me,
            reset_timer: true, dirty: true,
            next: vec![1; members], matched: vec![0; members], votes: vec![false; members],
            pending_snapshot: false,
        }
    }
    pub fn durable(&self) -> Durable {
        Durable { term: self.state.term, voted_for: self.state.voted_for, base: self.base,
            base_term: self.base_term, log: self.log.clone() }
    }
    pub fn restore(&mut self, d: Durable, snapshot: Vec<u8>) -> bool {
        if d.voted_for.map_or(false, |id| id >= self.members)
            || d.base_term > d.term || d.base.checked_add(d.log.len() as u64).is_none()
            || (d.base == 0 && (d.base_term != 0 || !snapshot.is_empty()))
            || d.log.iter().any(|e| e.term > d.term)
            || d.log.windows(2).any(|w| w[0].term > w[1].term)
            || d.log.first().map_or(false, |e| e.term < d.base_term)
        { return false; }
        self.state = State { term: d.term, voted_for: d.voted_for, role: Role::Follower };
        self.base = d.base;
        self.base_term = d.base_term;
        self.log = d.log;
        self.snapshot = snapshot;
        self.commit = self.base;
        self.applied = self.base;
        self.pending_snapshot = self.base != 0;
        self.dirty = false;
        true
    }
    pub fn end(&self) -> u64 { self.base + self.log.len() as u64 }
    pub fn term_at(&self, index: u64) -> Option<u64> {
        if index == self.base { Some(self.base_term) }
        else if index > self.base { self.log.get((index - self.base - 1) as usize).map(|e| e.term) }
        else { None }
    }
    fn observe(&mut self, term: u64) {
        if term > self.state.term {
            self.state.observe_term(term);
            self.dirty = true;
        }
    }
    pub fn election(&mut self) -> Option<Vote> {
        if self.state.is_leader() || !self.state.campaign(self.me) { return None; }
        self.dirty = true;
        self.reset_timer = true;
        self.votes.fill(false);
        self.votes[self.me] = true;
        let request = Vote { term: self.state.term, candidate: self.me,
            last_index: self.end(), last_term: self.term_at(self.end()).unwrap() };
        self.elect_if_majority();
        Some(request)
    }
    fn elect_if_majority(&mut self) {
        if self.state.role == Role::Candidate
            && state::majority(self.votes.iter().filter(|v| **v).count(), self.members)
        {
            self.state.role = Role::Leader;
            self.leader = self.me;
            // Exhausted indices stop proposals, but heartbeats remain permitted.
            self.next.fill(self.end().saturating_add(1));
            self.matched.fill(0);
            self.matched[self.me] = self.end();
        }
    }
    pub fn request_vote(&mut self, v: Vote) -> VoteReply {
        let local_index = self.end();
        let local_term = self.term_at(local_index).unwrap();
        let before = (self.state.term, self.state.voted_for);
        let granted = self.state.vote(v.term, v.candidate, self.members,
            v.last_term, v.last_index, local_term, local_index);
        self.dirty |= before != (self.state.term, self.state.voted_for);
        if granted { self.reset_timer = true; }
        VoteReply { term: self.state.term, granted }
    }
    pub fn vote_reply(&mut self, from: usize, sent: u64, r: VoteReply) {
        if from >= self.members { return; }
        self.observe(r.term);
        if self.state.role == Role::Candidate && self.state.term == sent && r.term == sent && r.granted {
            self.votes[from] = true;
            self.elect_if_majority();
        }
    }
    pub fn propose(&mut self, data: &[u8]) -> Option<(u64, u64)> {
        if !self.state.is_leader() { return None; }
        let index = self.end().checked_add(1)?;
        self.log.push(Entry { term: self.state.term, data: data.to_vec() });
        self.matched[self.me] = index;
        self.dirty = true;
        self.advance_commit();
        Some((index, self.state.term))
    }
    pub fn replication(&self, peer: usize) -> Option<Replication> {
        if !self.state.is_leader() || peer >= self.members || peer == self.me { return None; }
        let next = self.next[peer];
        if next <= self.base {
            Some(Replication::Snapshot(Install { term: self.state.term, leader: self.me,
                index: self.base, last_term: self.base_term, data: self.snapshot.clone() }))
        } else {
            let prev = next - 1;
            let offset = (prev - self.base) as usize;
            Some(Replication::Append(Append { term: self.state.term, leader: self.me,
                prev, prev_term: self.term_at(prev)?, entries: self.log.get(offset..)?.to_vec(), commit: self.commit }))
        }
    }
    pub fn append(&mut self, a: Append) -> AppendReply {
        let mut fail = AppendReply { term: self.state.term, success: false, next: self.end().saturating_add(1) };
        if a.leader >= self.members { return fail; }
        self.observe(a.term);
        fail.term = self.state.term;
        if a.term != self.state.term { return fail; }
        self.state.role = Role::Follower;
        self.leader = a.leader;
        self.reset_timer = true;
        if a.prev < self.base { fail.next = self.base.saturating_add(1); return fail; }
        if self.term_at(a.prev) != Some(a.prev_term) {
            if let Some(term) = self.term_at(a.prev) {
                let mut first = a.prev;
                while first > self.base && self.term_at(first - 1) == Some(term) { first -= 1; }
                fail.next = first.max(1);
            }
            return fail;
        }
        let end = match a.prev.checked_add(a.entries.len() as u64) { Some(x) => x, None => return fail };
        if a.entries.iter().any(|e| e.term > a.term)
            || a.entries.first().map_or(false, |e| e.term < a.prev_term)
            || a.entries.windows(2).any(|w| w[0].term > w[1].term) { return fail; }
        for (n, entry) in a.entries.into_iter().enumerate() {
            let index = a.prev + n as u64 + 1;
            let offset = (index - self.base - 1) as usize;
            if let Some(old) = self.log.get(offset) {
                if old == &entry { continue; }
                // Committed entries may never be overwritten, even on bad input.
                if index <= self.commit { return fail; }
                self.log.truncate(offset);
            }
            self.log.push(entry);
            self.dirty = true;
        }
        self.commit = self.commit.max(a.commit.min(end));
        AppendReply { term: self.state.term, success: true, next: end.saturating_add(1) }
    }
    pub fn append_reply(&mut self, peer: usize, sent: u64, prev: u64, end: u64, r: AppendReply) {
        if peer >= self.members || peer == self.me { return; }
        self.observe(r.term);
        if !state::same_epoch(self.state.role, self.state.term, sent) || r.term != sent { return; }
        if r.success {
            self.matched[peer] = self.matched[peer].max(end.min(self.end()));
            self.next[peer] = self.matched[peer].saturating_add(1);
            self.advance_commit();
        } else if self.next[peer] == prev.saturating_add(1) {
            // Failed obsolete RPCs cannot undo newer successful acknowledgments.
            self.next[peer] = r.next.min(prev).max(self.matched[peer].saturating_add(1)).max(1);
        }
    }
    fn advance_commit(&mut self) {
        for index in (self.commit.saturating_add(1)..=self.end()).rev() {
            let count = self.matched.iter().filter(|m| **m >= index).count();
            if state::commit_authorized(self.state.role, self.state.term,
                self.term_at(index).unwrap(), index, self.commit, self.end(), count, self.members) {
                self.commit = index;
                break;
            }
        }
    }
