        if !state::snapshot_authorized(self.base, index, self.applied, self.commit, self.end()) { return false; }
        let term = self.term_at(index).unwrap();
        self.log.drain(..(index - self.base) as usize);
        self.base = index;
        self.base_term = term;
        self.snapshot = data.to_vec();
        self.dirty = true;
        true
    }
