        if peer >= self.members || peer == self.me { return; }
        self.observe(r.term);
        if state::same_epoch(self.state.role, self.state.term, sent) && r.term == sent && r.accepted {
            self.matched[peer] = self.matched[peer].max(index.min(self.end()));
            self.next[peer] = self.matched[peer].saturating_add(1);
            self.advance_commit();
        }
    }
