        let mut result = vec![];
        if self.pending_snapshot {
            result.push(Applied::Snapshot { index: self.base, term: self.base_term, data: self.snapshot.clone() });
            self.pending_snapshot = false;
        }
        while self.applied < self.commit {
            self.applied += 1;
            result.push(Applied::Command { index: self.applied,
                data: self.log[(self.applied - self.base - 1) as usize].data.clone() });
        }
        result
    }
    pub fn snapshot_is_current(&self, term: u64, index: u64, data: &[u8]) -> bool {
        index == self.base && term == self.base_term && data == self.snapshot
    }
