#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InstallReply { pub term: u64, pub accepted: bool }

pub enum Replication { Append(Append), Snapshot(Install) }
pub enum Applied { Command { index: u64, data: Vec<u8> }, Snapshot { index: u64, term: u64, data: Vec<u8> } }

pub struct Core {
    pub state: State,
    pub me: usize,
    pub members: usize,
    pub base: u64,
    pub base_term: u64,
    pub log: Vec<Entry>,
    pub snapshot: Vec<u8>,
    pub commit: u64,
    pub applied: u64,
    pub leader: usize,
    pub reset_timer: bool,
    pub dirty: bool,
    next: Vec<u64>,
    matched: Vec<u64>,
    votes: Vec<bool>,
    pending_snapshot: bool,
}

impl Core {
    pub fn new(me: usize, members: usize) -> Self {
        assert!(members > 0 && me < members);
        Self {
            state: State::initial(), me, members, base: 0, base_term: 0,
            log: vec![], snapshot: vec![], commit: 0, applied: 0, leader: me,
            reset_timer: true, dirty: true,
            next: vec![1; members], matched: vec![0; members], votes: vec![false; members],
            pending_snapshot: false,
        }
    }
    pub fn durable(&self) -> Durable {
        Durable { term: self.state.term, voted_for: self.state.voted_for, base: self.base,
            base_term: self.base_term, log: self.log.clone() }
    }
    pub fn restore(&mut self, d: Durable, snapshot: Vec<u8>) -> bool {
        if d.voted_for.map_or(false, |id| id >= self.members)
            || d.base_term > d.term || d.base.checked_add(d.log.len() as u64).is_none()
            || (d.base == 0 && (d.base_term != 0 || !snapshot.is_empty()))
            || d.log.iter().any(|e| e.term > d.term)
            || d.log.windows(2).any(|w| w[0].term > w[1].term)
            || d.log.first().map_or(false, |e| e.term < d.base_term)
        { return false; }
        self.state = State { term: d.term, voted_for: d.voted_for, role: Role::Follower };
        self.base = d.base;
        self.base_term = d.base_term;
        self.log = d.log;
        self.snapshot = snapshot;
        self.commit = self.base;
        self.applied = self.base;
        self.pending_snapshot = self.base != 0;
        self.dirty = false;
        true
    }
    pub fn end(&self) -> u64 { self.base + self.log.len() as u64 }
    pub fn term_at(&self, index: u64) -> Option<u64> {
        if index == self.base { Some(self.base_term) }
        else if index > self.base { self.log.get((index - self.base - 1) as usize).map(|e| e.term) }
        else { None }
    }
    fn observe(&mut self, term: u64) {
