        AppendReply { term: self.state.term, success: true, next: end.saturating_add(1) }
    }
    pub fn append_reply(&mut self, peer: usize, sent: u64, prev: u64, end: u64, r: AppendReply) {
        if peer >= self.members || peer == self.me { return; }
        self.observe(r.term);
