            self.matched[peer] = self.matched[peer].max(end.min(self.end()));
            self.next[peer] = self.matched[peer].saturating_add(1);
            self.advance_commit();
        } else if self.next[peer] == prev.saturating_add(1) {
            // Failed obsolete RPCs cannot undo newer successful acknowledgments.
            self.next[peer] = r.next.min(prev).max(self.matched[peer].saturating_add(1)).max(1);
        }
    }
    fn advance_commit(&mut self) {
        for index in (self.commit.saturating_add(1)..=self.end()).rev() {
            let count = self.matched.iter().filter(|m| **m >= index).count();
            if state::commit_authorized(self.state.role, self.state.term,
                self.term_at(index).unwrap(), index, self.commit, self.end(), count, self.members) {
                self.commit = index;
                break;
            }
        }
    }
    pub fn compact(&mut self, index: u64, data: &[u8]) -> bool {
        if !state::snapshot_authorized(self.base, index, self.applied, self.commit, self.end()) { return false; }
        let term = self.term_at(index).unwrap();
        self.log.drain(..(index - self.base) as usize);
        self.base = index;
        self.base_term = term;
        self.snapshot = data.to_vec();
        self.dirty = true;
        true
    }
    pub fn install(&mut self, s: Install) -> InstallReply {
        if s.leader >= self.members { return InstallReply { term: self.state.term, accepted: false }; }
        self.observe(s.term);
        if s.term != self.state.term || s.last_term > s.term { return InstallReply { term: self.state.term, accepted: false }; }
