use crate::test_support::{create_node, start_node, node_id, kill};
use madsim::{net::NetSim, fs::FsSim, plugin::simulator};
use madsim::{time::*, runtime::{Handle, NodeHandle}};
use std::{
    net::SocketAddr,
    sync::atomic::{AtomicUsize, Ordering},
    sync::{Arc, Mutex},
};

use super::{client, server};

pub struct Tester {
    handle: Handle,
    n: usize,
    addrs: Vec<SocketAddr>,
    servers: Mutex<Vec<Option<Arc<server::KvServer>>>>,
    next_client_id: AtomicUsize,
    maxraftstate: Option<usize>,

    // begin()/end() statistics
    t0: Instant,
    // rpc_total() at start of test
    rpcs0: u64,
    // number of agreements
    ops: Arc<AtomicUsize>,
}

impl Tester {
    pub async fn new(n: usize, unreliable: bool, maxraftstate: Option<usize>) -> Tester {
        let handle = Handle::current();
        let addrs = (0..n)
                .map(|i| SocketAddr::from(([0, 0, 1, i as _], 1)))
                .collect::<Vec<_>>();
        for &addr in &addrs { create_node(&handle, addr); }
        if unreliable {
            NetSim::current().update_config(|cfg| {
                cfg.packet_loss_rate = 0.1;
                cfg.send_latency = Duration::from_millis(1)..Duration::from_millis(27);
            });
        }
        let mut servers = vec![];
        servers.resize_with(n, || None);
        let mut tester = Tester {
            handle,
            n,
            addrs,
            servers: Mutex::new(servers),
            next_client_id: AtomicUsize::new(0),
            maxraftstate,
            t0: Instant::now(),
            rpcs0: 0,
            ops: Arc::new(AtomicUsize::new(0)),
        };
        tester.rpcs0 = tester.rpc_total();
        // create a full set of KV servers.
        for i in 0..n {
            tester.start_server(i).await;
        }
        tester
    }

    fn rpc_total(&self) -> u64 {
        NetSim::current().stat().msg_count / 2
    }

    fn check_timeout(&self) {
        // enforce a two minute real-time limit on each test
        if self.t0.elapsed() > Duration::from_secs(120) {
            panic!("test took longer than 120 seconds");
        }
    }

    /// Maximum log size across all servers
    pub fn log_size(&self) -> usize {
        self.addrs
            .iter()
            .map(|&addr| simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "state").unwrap())
            .max()
            .unwrap() as usize
    }

    /// Maximum snapshot size across all servers
    pub fn snapshot_size(&self) -> usize {
        self.addrs
            .iter()
            .map(|&addr| simulator::<FsSim>().get_file_size(node_id(&self.handle, addr), "snapshot").unwrap())
            .max()
            .unwrap() as usize
    }

    /// Attach server i to servers listed in to
    fn connect(&self, i: usize, to: &[usize]) {
        debug!("connect peer {} to {:?}", i, to);
        for &j in to {
            NetSim::current().connect2(node_id(&self.handle, self.addrs[i]), node_id(&self.handle, self.addrs[j]));
        }
    }

    /// Detach server i from the servers listed in from
    fn disconnect(&self, i: usize, from: &[usize]) {
        debug!("disconnect peer {} from {:?}", i, from);
        for &j in from {
            NetSim::current().disconnect2(node_id(&self.handle, self.addrs[i]), node_id(&self.handle, self.addrs[j]));
        }
    }

    pub fn all(&self) -> Vec<usize> {
        (0..self.n).collect()
    }

    pub fn connect_all(&self) {
        for i in 0..self.n {
            self.connect(i, &self.all());
        }
    }

    /// Sets up 2 partitions with connectivity between servers in each  partition.
    pub fn partition(&self, p1: &[usize], p2: &[usize]) {
        debug!("partition servers into: {:?} {:?}", p1, p2);
        for &i in p1 {
            self.disconnect(i, p2);
            self.connect(i, p1);
        }
        for &i in p2 {
            self.disconnect(i, p1);
            self.connect(i, p2);
        }
    }

    // Create a clerk with clerk specific server names.
    // Give it connections to all of the servers, but for
    // now enable only connections to servers in to[].
    pub fn make_client(&self, to: &[usize]) -> Clerk {
        let id = ClerkId(self.next_client_id.fetch_add(1, Ordering::SeqCst));
        create_node(&self.handle, id.to_addr());
        self.connect_client(id, to);
        Clerk {
            id,
            handle: start_node(&self.handle, id.to_addr()),
            ck: Arc::new(client::Clerk::new(self.addrs.clone())),
            ops: self.ops.clone(),
        }
    }

    pub fn connect_client(&self, id: ClerkId, to: &[usize]) {
        debug!("connect {:?} to {:?}", id, to);
        let addr = id.to_addr();
        NetSim::current().connect(node_id(&self.handle, addr));
        for i in 0..self.n {
            NetSim::current().disconnect2(node_id(&self.handle, addr), node_id(&self.handle, self.addrs[i]));
        }
        for &i in to {
            NetSim::current().connect2(node_id(&self.handle, addr), node_id(&self.handle, self.addrs[i]));
        }
    }

    /// Shutdown a server.
    pub fn shutdown_server(&self, i: usize) {
        debug!("shutdown_server({})", i);
        kill(&self.handle, self.addrs[i]);
        self.servers.lock().unwrap()[i] = None;
    }

    /// Start a server.
    /// If restart servers, first call shutdown_server
    pub async fn start_server(&self, i: usize) {
        debug!("start_server({})", i);
        let addrs = self.addrs.clone();
        let handle = start_node(&self.handle, self.addrs[i]);
        let kv = handle
            .spawn(server::KvServer::new(addrs, i, self.maxraftstate))
            .await.unwrap();
        self.servers.lock().unwrap()[i] = Some(kv);
    }

    pub fn leader(&self) -> Option<usize> {
        let servers = self.servers.lock().unwrap();
        for (i, kv) in servers.iter().enumerate() {
            if let Some(kv) = kv {
                if kv.is_leader() {
                    return Some(i);
                }
            }
        }
        None
    }

    /// Partition servers into 2 groups and put current leader in minority
    pub fn make_partition(&self) -> (Vec<usize>, Vec<usize>) {
        let leader = self.leader().unwrap_or(0);
        let mut p1 = (0..self.n).collect::<Vec<usize>>();
        p1.swap_remove(leader);
        let mut p2 = p1.split_off(self.n / 2 + 1);
        p2.push(leader);
        (p1, p2)
    }

    /// End a Test -- the fact that we got here means there
    /// was no failure.
    /// print the Passed message,
    /// and some performance numbers.
    pub fn end(&self) {
        self.check_timeout();

        // real time
        let t = self.t0.elapsed();
        // number of Raft peers
        let npeers = self.n;
        // number of RPC sends
        let nrpc = self.rpc_total() - self.rpcs0;
        // number of clerk get/put/append calls
        let nops = self.ops.load(Ordering::Relaxed);

        info!("  ... Passed --");
        info!("  {:?}  {} {} {}", t, npeers, nrpc, nops);
    }
}

#[derive(Debug, Clone, Copy, Hash, PartialEq, Eq, PartialOrd, Ord)]
pub struct ClerkId(usize);

impl ClerkId {
    fn to_addr(&self) -> SocketAddr {
        SocketAddr::from(([0, 0, 2, self.0 as u8], 1))
    }
}

pub struct Clerk {
    handle: NodeHandle,
    id: ClerkId,
    ck: Arc<client::Clerk>,
    ops: Arc<AtomicUsize>,
}

impl Clerk {
    pub const fn id(&self) -> ClerkId {
        self.id
    }

    pub async fn put(&self, key: &str, value: &str) {
        self.op();
        let ck = self.ck.clone();
        let key = key.to_owned();
        let value = value.to_owned();
        self.handle
            .spawn(async move {
                ck.put(key, value).await;
            })
            .await.unwrap()
    }

    pub async fn append(&self, key: &str, value: &str) {
        self.op();
        let ck = self.ck.clone();
        let key = key.to_owned();
        let value = value.to_owned();
        self.handle
            .spawn(async move {
                ck.append(key, value).await;
            })
            .await.unwrap()
    }

    pub async fn get(&self, key: &str) -> String {
        self.op();
        let ck = self.ck.clone();
        let key = key.to_owned();
        self.handle.spawn(async move { ck.get(key).await }).await.unwrap()
    }

    pub async fn check(&self, key: &str, value: &str) {
        let ck = self.ck.clone();
        let key1 = key.to_owned();
        let actual = self.handle.spawn(async move { ck.get(key1).await }).await.unwrap();
        assert_eq!(actual, value, "get({}) check failed", key);
    }

    fn op(&self) {
        self.ops.fetch_add(1, Ordering::Relaxed);
    }
}
