impl ShardKvServer {
    pub async fn new(ctrl_ck: CtrlerClerk, servers: Vec<SocketAddr>, gid: u64, me: usize, max_raft_state: Option<usize>) -> Arc<Self> {
        let initial = ShardKv { gid, ..ShardKv::default() };
