    requires a.len() == b.len(), votes(a, a.len()) > a.len() / 2, votes(b, b.len()) > b.len() / 2,
    ensures exists|i: int| 0 <= i < a.len() && a[i] && b[i],
{
    if !(exists|i: int| 0 <= i < a.len() && a[i] && b[i]) {
        disjoint_vote_bound(a, b, a.len());
    }
}
}
